def work_on_strings(a: str, b: str) -> str:
    def swap_case(char: str) -> str:
        if char.islower():
            return char.upper()
        elif char.isupper():
            return char.lower()
        return char

    def process(target: str, source: str) -> str:
        target_list = list(target)
        for s_char in source:
            for i in range(len(target_list)):
                t_char = target_list[i]
                if t_char.lower() == s_char.lower():
                    target_list[i] = swap_case(t_char)
        return "".join(target_list)

    modified_b = process(b, a)
    modified_a = process(a, modified_b)

    return modified_a + modified_b
